transitions.beforeText:
﻿$ErrorActionPreference='Stop'
$script:WatchdogRoot='G:/207/项目/算法重组工具/代码/agent-platform'
if(!('OwnedDeadline' -as [type])){Add-Type -Path "$PSScriptRoot/iam-model-local-meter-watchdog-fix-deadline.cs"}
$script:OwnedProcesses=[Collections.Generic.List[object]]::new()
function Write-OwnJson($Path,$Value){$Value | ConvertTo-Json -Depth 30 | Set-Content -LiteralPath $Path -Encoding utf8}
function Register-OwnProcess($Process,$Role,$ParentId=0){
 $Process.Refresh()
 $r=[pscustomobject]@{pid=$Process.Id;startTicks=$Process.StartTime.ToUniversalTime().Ticks;role=$Role;parent=$ParentId;process=$Process}
 $script:OwnedProcesses.Add($r)
 return $r
}
function Test-OwnAlive($Record){
 try{$p=[Diagnostics.Process]::GetProcessById($Record.pid);return (!$p.HasExited -and $p.StartTime.ToUniversalTime().Ticks -eq $Record.startTicks)}catch{return $false}
}
function Find-OwnDescendants($Records,$Guard){
 foreach($r in @($Records.ToArray())){
  if(!(Test-OwnAlive $r)){continue}
  # Only query children of a registered, still-identical parent, never an OS-wide census.
  foreach($c in @(Get-CimInstance Win32_Process -Filter "ParentProcessId = $($r.pid)")){
   if(@($Records | Where-Object {$_.pid -eq [int]$c.ProcessId}).Count -gt 0){continue}
   try{$p=[Diagnostics.Process]::GetProcessById([int]$c.ProcessId);$n=Register-OwnProcess $p 'descendant' $r.pid;$Records.Add($n);$Guard.Add($p,$n.startTicks)}catch{}
  }
 }
}
function Stop-OwnProcesses($Records){
 $sw=[Diagnostics.Stopwatch]::StartNew();$out=@()
 foreach($r in @($Records.ToArray()) | Sort-Object startTicks -Descending){
  $alive=Test-OwnAlive $r;$forced=$false
  if($alive){$r.process.Kill();$forced=$true}
  $out+=@{pid=$r.pid;startTicks=$r.startTicks;forced=$forced}
 }
 foreach($r in @($Records.ToArray())){
  if(Test-OwnAlive $r){$remaining=[Math]::Max(0,10000-[int]$sw.ElapsedMilliseconds);$r.process.WaitForExit($remaining)|Out-Null}
 }
 foreach($o in $out){$r=@($Records|Where-Object {$_.pid -eq $o.pid})[0];$o.aliveAfter=Test-OwnAlive $r}
 if(@($out|Where-Object {$_.aliveAfter}).Count -gt 0){throw 'OWN_CLEANUP_10S_FAILED'}
 return @{elapsedMs=$sw.ElapsedMilliseconds;processes=$out}
}
function Invoke-OwnBoundedProcess {
 param([string]$Executable,[string[]]$Arguments,[string]$Role,[string]$Evidence,[double]$CapSeconds=30)
 # Validation occurs before launch. A child never receives a silently enlarged bound.
 if($CapSeconds -le 0 -or $CapSeconds -gt 30){throw 'EXTERNAL_CAP_MUST_BE_POSITIVE_AND_LE_30_SECONDS'}
 if((Get-Location).Path.Replace('\','/') -ne $script:WatchdogRoot){throw 'FIXED_CWD_REQUIRED'}
 $records=[Collections.Generic.List[object]]::new();$sw=[Diagnostics.Stopwatch]::StartNew();$guard=[OwnedDeadline]::new($CapSeconds);$disposed=$false
 $result=[ordered]@{executable=$Executable;arguments=$Arguments;cwd=$script:WatchdogRoot;capSeconds=$CapSeconds;startedUtc=[DateTime]::UtcNow.ToString('O');timedOut=$false;forced=$false}
 try{
  $p=Start-Process -FilePath $Executable -ArgumentList $Arguments -WorkingDirectory $script:WatchdogRoot -WindowStyle Hidden -RedirectStandardOutput ($Evidence+'.stdout.log') -RedirectStandardError ($Evidence+'.stderr.log') -PassThru
  $records.Add((Register-OwnProcess $p $Role));$guard.Add($p,$records[0].startTicks);$result.rootPid=$p.Id
  while(!$p.HasExited -and !$guard.Fired){
   Find-OwnDescendants $records $guard
   $p.WaitForExit(50)|Out-Null
  }
  $guard.Dispose();$disposed=$true
  $result.timedOut=$guard.Fired;$result.forced=$guard.Fired
  if($guard.Fired){$result.killDecisionMs=$guard.DecisionMs;$result.killErrors=$guard.Errors}
  $result.cleanup=Stop-OwnProcesses $records
  $p.Refresh();$result.rootAliveAtReturn=Test-OwnAlive $records[0]
  $result.exit=if($p.HasExited){$p.ExitCode}else{$null}
  $result.elapsedMs=$sw.ElapsedMilliseconds
  return [pscustomobject]$result
 }finally{
  if(!$disposed){$guard.Dispose()}
  $result.identities=@($records|ForEach-Object {@{pid=$_.pid;startTicks=$_.startTicks;role=$_.role;parent=$_.parent;alive=Test-OwnAlive $_}})
  $result.endedUtc=[DateTime]::UtcNow.ToString('O')
  Write-OwnJson ($Evidence+'.json') $result
 }
}

