$ErrorActionPreference='Stop'
$script:WatchdogRoot='G:/207/项目/算法重组工具/代码/agent-platform'
if(!('ReviewOwnedDeadline' -as [type])){Add-Type -Path "$PSScriptRoot/iam-model-local-meter-watchdog-review-fix-deadline.cs"}
$script:OwnedProcesses=[Collections.Generic.List[object]]::new()
function Write-OwnJson($Path,$Value){$Value | ConvertTo-Json -Depth 30 | Set-Content -LiteralPath $Path -Encoding utf8}
function Register-OwnProcess($Process,$Role,$ParentId=0,$CreationUtc=$null,$ParentRecord=$null){
 try{
  # Opening and retaining this handle pins the process object; later checks never reopen its PID.
  $null=$Process.Handle;$Process.Refresh();if($Process.HasExited){return $null}
  $ticks=$Process.StartTime.ToUniversalTime().Ticks
  if($ParentId -ne 0){
   if($null -eq $ParentRecord -or $ParentRecord.pid -ne $ParentId -or !(Test-OwnAlive $ParentRecord)){return $null}
   if($CreationUtc -isnot [DateTime]){return $null}
   $candidateTicks=$CreationUtc.ToUniversalTime().Ticks
   # Win32_Process exposes microseconds. Compare the exact truncated microsecond, never a time tolerance.
   if($candidateTicks % 10 -ne 0 -or ($ticks-($ticks % 10)) -ne $candidateTicks){return $null}
   if($Process.HasExited -or !(Test-OwnAlive $ParentRecord)){return $null}
  }
  $r=[pscustomobject]@{pid=$Process.Id;startTicks=$ticks;role=$Role;parent=$ParentId;process=$Process}
  $script:OwnedProcesses.Add($r);return $r
 }catch{if($ParentId -ne 0){return $null};throw}
}
function Test-OwnAlive($Record){
 try{$p=$Record.process;$p.Refresh();return (!$p.HasExited -and $p.StartTime.ToUniversalTime().Ticks -eq $Record.startTicks)}catch{return $false}
}
function Find-OwnDescendants($Records,$Guard){
 foreach($r in @($Records.ToArray())){
  if(!(Test-OwnAlive $r)){continue}
  # Only sampled children of a registered, still-identical parent; no global census.
  $children=@(Get-CimInstance Win32_Process -Filter "ParentProcessId = $($r.pid)")
  if(!(Test-OwnAlive $r)){continue}
  foreach($c in $children){
   if(!(Test-OwnAlive $r)){break}
   if(@($Records|Where-Object {$_.pid -eq [int]$c.ProcessId}).Count -gt 0){continue}
   try{$p=[Diagnostics.Process]::GetProcessById([int]$c.ProcessId)}catch{continue}
   $n=Register-OwnProcess $p 'descendant' $r.pid $c.CreationDate $r
   if($null -ne $n){$Records.Add($n);$Guard.Add($p,$n.startTicks)}else{$p.Dispose()}
  }
 }
}
function Stop-OwnProcesses($Records){
 $sw=[Diagnostics.Stopwatch]::StartNew();$out=@();$errors=@()
 foreach($r in @($Records.ToArray())|Sort-Object startTicks -Descending){
  $forced=$false
  try{if(Test-OwnAlive $r){$r.process.Kill();$forced=$true}}catch{$errors+="$($r.pid):$($_.Exception.Message)"}
  $out+=@{pid=$r.pid;startTicks=$r.startTicks;forced=$forced}
 }
 foreach($r in @($Records.ToArray())){
  try{if(Test-OwnAlive $r){$r.process.WaitForExit([Math]::Max(0,10000-[int]$sw.ElapsedMilliseconds))|Out-Null}}catch{$errors+="$($r.pid):$($_.Exception.Message)"}
 }
 foreach($o in $out){$r=@($Records|Where-Object {$_.pid -eq $o.pid -and $_.startTicks -eq $o.startTicks})[0];$o.aliveAfter=Test-OwnAlive $r}
 $result=@{elapsedMs=$sw.ElapsedMilliseconds;processes=$out;errors=$errors}
 if(@($out|Where-Object {$_.aliveAfter}).Count -gt 0){$e=[Exception]::new('OWN_CLEANUP_10S_FAILED');$e.Data['cleanup']=$result;throw $e}
 return $result
}
function Invoke-OwnBoundedProcess {
 param([string]$Executable,[string[]]$Arguments,[string]$Role,[string]$Evidence,[double]$CapSeconds=30)
 if([double]::IsNaN($CapSeconds) -or [double]::IsInfinity($CapSeconds) -or $CapSeconds -le 0 -or $CapSeconds -gt 30){throw 'EXTERNAL_CAP_MUST_BE_POSITIVE_AND_LE_30_SECONDS'}
 if((Get-Location).Path.Replace('\','/') -ne $script:WatchdogRoot){throw 'FIXED_CWD_REQUIRED'}
 $records=[Collections.Generic.List[object]]::new();$sw=[Diagnostics.Stopwatch]::StartNew();$guard=[ReviewOwnedDeadline]::new($CapSeconds)
 $primary=$null;$secondary=[Collections.Generic.List[string]]::new()
 $result=[ordered]@{executable=$Executable;arguments=$Arguments;cwd=$script:WatchdogRoot;capSeconds=$CapSeconds;startedUtc=[DateTime]::UtcNow.ToString('O');timedOut=$false;forced=$false}
 try{
  $p=Start-Process -FilePath $Executable -ArgumentList $Arguments -WorkingDirectory $script:WatchdogRoot -WindowStyle Hidden -RedirectStandardOutput ($Evidence+'.stdout.log') -RedirectStandardError ($Evidence+'.stderr.log') -PassThru
  $r=Register-OwnProcess $p $Role;if($null -eq $r){throw 'OWN_LAUNCH_IDENTITY_UNVERIFIABLE'}
  $records.Add($r);$guard.Add($p,$r.startTicks);$result.rootPid=$p.Id
  while(!$p.HasExited -and !$guard.Fired){
   Find-OwnDescendants $records $guard
   if($script:WaitControl){& $script:WaitControl $records}
   $p.WaitForExit(50)|Out-Null
  }
 }catch{$primary=$_;$result.primaryFailure=$_.Exception.Message}
 finally{
  # Keep the deadline armed until this invocation's own records are stopped on EVERY exit.
  try{$result.cleanup=Stop-OwnProcesses $records}catch{
   if($_.Exception.Data.Contains('cleanup')){$result.cleanup=$_.Exception.Data['cleanup']}
   if(!$primary){$primary=$_;$result.primaryFailure=$_.Exception.Message}else{$secondary.Add('cleanup:'+ $_.Exception.Message)}
  }finally{
   try{$guard.Dispose();$result.timerDisposedAndCallbacksCompleted=$true}catch{if(!$primary){$primary=$_;$result.primaryFailure=$_.Exception.Message}else{$secondary.Add('timer:'+ $_.Exception.Message)}}
   finally{
    $result.timedOut=$guard.Fired;$result.forced=($guard.Fired -or @($result.cleanup.processes|Where-Object {$_.forced}).Count -gt 0)
    if($guard.Fired){$result.killDecisionMs=$guard.DecisionMs};$result.killErrors=$guard.Errors
    $result.identities=@($records|ForEach-Object {@{pid=$_.pid;startTicks=$_.startTicks;role=$_.role;parent=$_.parent;alive=Test-OwnAlive $_}})
    $result.rootAliveAtReturn=($records.Count -gt 0 -and (Test-OwnAlive $records[0]))
    $result.exit=if($p -and $p.HasExited){$p.ExitCode}else{$null};$result.elapsedMs=$sw.ElapsedMilliseconds;$result.endedUtc=[DateTime]::UtcNow.ToString('O');$result.secondaryFailures=$secondary.ToArray()
    try{Write-OwnJson ($Evidence+'.json') $result}catch{if(!$primary){$primary=$_}else{$primary.Exception.Data['evidenceFailure']=$_.Exception.Message}}
   }
  }
 }
 if($primary){$primary.Exception.Data['ownResult']=$result;throw $primary}
 return [pscustomobject]$result
}

