using System.Collections.Concurrent;
using System.Diagnostics;
using System.Threading;
public sealed class ReviewOwnedDeadline : IDisposable {
 readonly ConcurrentDictionary<int,(Process process,long ticks)> owned = new();
 readonly ConcurrentQueue<string> errors = new();
 readonly Stopwatch watch = Stopwatch.StartNew();
 readonly Timer timer;
 int fired;
 public bool Fired => Volatile.Read(ref fired) != 0;
 public long DecisionMs {get; private set;}
 public string[] Errors => errors.ToArray();
 public ReviewOwnedDeadline(double seconds) {
  if(seconds<=0 || seconds>30) throw new ArgumentOutOfRangeException(nameof(seconds));
  timer=new Timer(_=>Expire(),null,TimeSpan.FromSeconds(seconds),Timeout.InfiniteTimeSpan);
 }
 public void Add(Process p,long ticks) {
  owned.TryAdd(p.Id,(p,ticks));
  if(Fired) Kill(p,ticks);
 }
 void Kill(Process p,long ticks) {
  try { if(!p.HasExited && p.StartTime.ToUniversalTime().Ticks==ticks) p.Kill(); }
  catch(Exception e) { errors.Enqueue(p.Id+":"+e.GetType().Name); }
 }
 void Expire() {
  DecisionMs=watch.ElapsedMilliseconds;
  Interlocked.Exchange(ref fired,1);
  foreach(var item in owned.Values) Kill(item.process,item.ticks);
 }
 public void Dispose() {
  using var done=new ManualResetEvent(false);
  if(timer.Dispose(done) && !done.WaitOne(TimeSpan.FromSeconds(10))) throw new TimeoutException("OWN_TIMER_STOP_10S");
 }
}

