param([ValidateSet('red','green')][string]$Phase)
$ErrorActionPreference='Stop'
. "$PSScriptRoot/iam-model-local-meter-watchdog-review-fix-wait.ps1"
$base="$script:WatchdogRoot/.local/iam-model-local-meter-watchdog-review-fix/controls/$Phase"
New-Item -ItemType Directory -Path $base -Force|Out-Null
$pwsh=Join-Path $PSHOME 'pwsh.exe'
$script:treePidFile="$base/child.pid"
$tree="$PSScriptRoot/iam-model-local-meter-watchdog-review-fix-tree.ps1"
$hung="$PSScriptRoot/iam-model-local-meter-watchdog-review-fix-hung.ps1"
$result=[ordered]@{phase=$Phase;startedUtc=[DateTime]::UtcNow.ToString('O')}
try{
 $script:WaitControl={param($records)
  if(Test-Path $script:treePidFile){$childId=[int](Get-Content $script:treePidFile);if(@($records|Where-Object {$_.pid -eq $childId}).Count -gt 0){throw 'CONTROL_INSIDE_WAIT_AFTER_DESCENDANT_REGISTRATION'}}
 }
 $primary=$null
 try{Invoke-OwnBoundedProcess $pwsh @('-NoProfile','-File',('"'+$tree+'"'),'-ChildScript',('"'+$hung+'"'),'-PidFile',('"'+$script:treePidFile+'"')) 'exception-tree' "$base/inside-wait" 5|Out-Null}catch{$primary=$_.Exception.Message}
 $script:WaitControl=$null
 $result.insideWaitPrimary=$primary
 $result.insideWaitIdentityCount=$script:OwnedProcesses.Count
 $result.insideWaitClosedBeforeCaller=($primary -eq 'CONTROL_INSIDE_WAIT_AFTER_DESCENDANT_REGISTRATION' -and $script:OwnedProcesses.Count -ge 2 -and @($script:OwnedProcesses|Where-Object {Test-OwnAlive $_}).Count -eq 0)
 $result.insideWaitSafetyCleanup=Stop-OwnProcesses $script:OwnedProcesses
 # One genuine own parent/child; mismatch supplies a different creation time for that same child.
 $candidateRecords=[Collections.Generic.List[object]]::new();$candidateGuard=[ReviewOwnedDeadline]::new(5)
 try{
  $p=Start-Process $pwsh -ArgumentList @('-NoProfile','-File',('"'+$tree+'"'),'-ChildScript',('"'+$hung+'"'),'-PidFile',('"'+$base+'/candidate.pid"')) -WorkingDirectory $script:WatchdogRoot -WindowStyle Hidden -RedirectStandardOutput "$base/candidate.stdout.log" -RedirectStandardError "$base/candidate.stderr.log" -PassThru
  $parent=Register-OwnProcess $p 'candidate-parent';$candidateRecords.Add($parent);$candidateGuard.Add($p,$parent.startTicks)
  $sw=[Diagnostics.Stopwatch]::StartNew();$c=$null
  while(!$c -and $sw.Elapsed.TotalSeconds -lt 3){
   if(Test-Path "$base/candidate.pid"){$childId=[int](Get-Content "$base/candidate.pid");$c=Get-CimInstance Win32_Process -Filter "ParentProcessId = $($parent.pid)"|Where-Object {$_.ProcessId -eq $childId}}
   if(!$c){Start-Sleep -Milliseconds 50}
  }
  if(!$c){throw 'CONTROL_CHILD_NOT_FOUND'}
  $child=[Diagnostics.Process]::GetProcessById([int]$c.ProcessId);$null=$child.Handle
  $before=$script:OwnedProcesses.Count
  $mismatch=Register-OwnProcess $child 'candidate-mismatch' $parent.pid ($c.CreationDate.ToUniversalTime().AddSeconds(-1)) $parent
  $result.candidateMismatchRejected=($null -eq $mismatch -and $script:OwnedProcesses.Count -eq $before -and !$child.HasExited)
  if($mismatch){$script:OwnedProcesses.Remove($mismatch)|Out-Null}
  $match=Register-OwnProcess $child 'candidate-matched' $parent.pid $c.CreationDate.ToUniversalTime() $parent
  $result.candidateMatchedAccepted=($null -ne $match)
  $result.creationPrecision=@{cimTicks=$c.CreationDate.ToUniversalTime().Ticks;openedTicks=$child.StartTime.ToUniversalTime().Ticks;differenceTicks=($child.StartTime.ToUniversalTime().Ticks-$c.CreationDate.ToUniversalTime().Ticks)}
  if(!$match){throw 'CONTROL_MATCHED_CANDIDATE_REJECTED'}
  $candidateRecords.Add($match);$candidateGuard.Add($child,$match.startTicks)
 }finally{$result.candidateCleanup=Stop-OwnProcesses $candidateRecords;$candidateGuard.Dispose()}
 $healthy=Invoke-OwnBoundedProcess $pwsh @('-NoProfile','-File',('"'+$PSScriptRoot+'/iam-model-local-meter-watchdog-review-fix-healthy.ps1"')) 'healthy' "$base/healthy" 3
 $result.healthyPassed=($healthy.exit -eq 0 -and !$healthy.timedOut)
 $before=$script:OwnedProcesses.Count
 try{Invoke-OwnBoundedProcess $pwsh @() 'invalid-cap' "$base/invalid" 30.01|Out-Null;$result.invalidRejected=$false}catch{$result.invalidRejected=($_.Exception.Message -eq 'EXTERNAL_CAP_MUST_BE_POSITIVE_AND_LE_30_SECONDS' -and $script:OwnedProcesses.Count -eq $before)}
 $result.passed=($result.insideWaitClosedBeforeCaller -and $result.candidateMismatchRejected -and $result.candidateMatchedAccepted -and $result.healthyPassed -and $result.invalidRejected)
}finally{
 $script:WaitControl=$null
 $result.finalCleanup=Stop-OwnProcesses $script:OwnedProcesses
 $result.endedUtc=[DateTime]::UtcNow.ToString('O');Write-OwnJson "$base/result.json" $result
}
$result|ConvertTo-Json -Depth 12
if(!$result.passed){exit 1}

